const OLD_KEYS=['minha_meta_v14','minha_meta_v13','minha_meta_v12','minha_meta_v11','minha_meta_v10','minha_meta_v9'];
const fmt=n=>new Intl.NumberFormat('es-AR',{maximumFractionDigits:0}).format(Number(n||0));
const money=n=>'$ '+fmt(n);
const localISO=()=>{const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10)};
const uid=()=>Date.now()+Math.floor(Math.random()*1000);
