const initial={version:15,cycleId:uid(),cycleName:'Ciclo atual',periodStart:'2026-09-01',periodEnd:'2026-10-05',obligationsGoal:0,safetyMargin:100000,goal:100000,obligations:[],lastBackup:null,selectedDate:localISO(),incomes:[],expenses:[],study:[],quality:{},reminders:[],dailyActivities:{},bills:[],budgets:[],cycles:[],plannedActivityOverrides:{},dayStatus:{}};
