function obligationTotal(){return sum(data.bills,b=>b.amount)}
function recalcGoal(){data.obligationsGoal=obligationTotal();data.goal=data.obligationsGoal+Number(data.safetyMargin||0)}
function save(){localStorage.setItem(KEY,JSON.stringify(data));render()}
function sum(a,f){return a.reduce((s,x)=>s+Number(f(x)||0),0)}
function formatDate(d){return new Intl.DateTimeFormat('pt-BR',{timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'))}
function daysBetween(a,b){return Math.ceil((new Date(b+'T23:59:59')-new Date(a+'T00:00:00'))/86400000)+1}
function cycleDaysRemaining(){return Math.max(0,daysBetween(localISO(),data.periodEnd))}
function incomeTotal(){return sum(data.incomes,x=>x.amount)}
function expenseTotal(){return sum(data.expenses,x=>x.amount)}
function plannedGoals(){let total=0;for(let d=new Date(data.periodStart+'T12:00');d<=new Date(data.periodEnd+'T12:00');d.setDate(d.getDate()+1))total+=plannedGoalFor(d.toISOString().slice(0,10));return total}
const plannedGoalsByDay={0:70000,1:0,2:59204,3:106250,4:64830,5:125455,6:142500};
const plannedGoalOverrides={'2026-10-02':125456};
const plannedHoursByDay={0:5,1:0,2:4.5,3:8.5,4:4.5,5:8.5,6:9.5};
function plannedGoalFor(date){const dow=new Date(date+'T12:00').getDay();return data.plannedActivityOverrides?.[date]?.workTarget??plannedGoalOverrides[date]??(data.weeklyWorkTargets?.[dow]??plannedGoalsByDay[dow]??0)}
function futureWorkDates(){const out=[];const start=new Date(localISO()+'T12:00'), end=new Date(data.periodEnd+'T12:00');for(let d=new Date(start);d<=end;d.setDate(d.getDate()+1)){const iso=d.toISOString().slice(0,10);if(plannedGoalFor(iso)>0&&!data.dayStatus?.[iso]?.closed)out.push(iso)}return out}
function remainingWorkDays(){return futureWorkDates().length}
function plannedFutureTotal(){return sum(futureWorkDates(),d=>plannedGoalFor(d))}
function closedPlanDeficit(){return sum(Object.keys(data.dayStatus||{}).filter(d=>data.dayStatus[d]?.closed),d=>Math.max(0,plannedGoalFor(d)-incomeForDay(d)))}
function closedPlanSurplus(){return sum(Object.keys(data.dayStatus||{}).filter(d=>data.dayStatus[d]?.closed),d=>Math.max(0,incomeForDay(d)-plannedGoalFor(d)))}
function planningGap(){return Math.max(0,Number(data.goal||0)-incomeTotal())-plannedFutureTotal()}
function planningExcess(){return plannedFutureTotal()-Math.max(0,Number(data.goal||0)-incomeTotal())}
function planningStatus(){const gap=planningGap();if(Math.abs(gap)<0.5)return 'balanced';return gap>0?'short':'over'}
function dayPlan(date){const dow=new Date(date+'T12:00').getDay();const overrides=data.plannedActivityOverrides?.[date]||{};const base=(data.weeklyActivities?.[dow]||[]).map((x,i)=>{const id=x.id||'base-'+dow+'-'+i;const o=overrides[id]||{};if(o.removed)return null;return {id,icon:x.icon||'📌',name:o.name||x.name,metric:o.metric||x.metric,target:o.target??((o.metric||x.metric)==='money'?plannedGoalFor(date):x.target),done:Boolean(o.done),actual:o.actual??0,editable:true,weekly:true}}).filter(Boolean);return [...base,...(data.dailyActivities[date]||[])].map(x=>({...x,editable:x.editable!==false}))}
function activityProgress(a,date){if(a.metric==='money'){const actual=incomeForDay(date);const target=Number(a.target||plannedGoalFor(date));return {actual,target,pct:target?Math.min(100,actual/target*100):0,label:money(actual)+' / '+money(target)}}if(a.metric==='hours'){const actual=studyForDay(date);return {actual,target:Number(a.target||0),pct:a.target?Math.min(100,actual/a.target*100):0,label:actual.toFixed(1).replace('.',',')+'h / '+Number(a.target||0).toFixed(1).replace('.',',')+'h'}}return {actual:a.done?1:0,target:1,pct:a.done?100:0,label:a.done?'Concluída':'Pendente'}}
function incomeForDay(d){return sum(data.incomes.filter(x=>x.date===d),x=>x.amount)}
function studyForDay(d){return sum(data.study.filter(x=>x.date===d),x=>x.hours)}
function go(id){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');window.scrollTo(0,0);render()}
function selected(){return data.selectedDate}
function selectDate(d){if(d){data.selectedDate=d;save()}}
function changeDay(n){const d=new Date(selected()+'T12:00');d.setDate(d.getDate()+n);data.selectedDate=d.toISOString().slice(0,10);save()}
