 const sd=selected(),income=incomeTotal(),expense=expenseTotal(),net=income-expense,goal=Number(data.goal||0),pct=goal?Math.min(100,income/goal*100):0,remaining=Math.max(0,goal-income),days=remainingWorkDays(),needed=days?Math.ceil(remaining/days):remaining,closed=Boolean(data.dayStatus?.[sd]?.closed),dayTarget=plannedGoalFor(sd),dayGain=incomeForDay(sd),dayDiff=dayGain-dayTarget,futurePlan=plannedFutureTotal(),gap=planningGap(),excess=planningExcess(),closedDeficit=closedPlanDeficit(),closedSurplus=closedPlanSurplus();
 const label=new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date(sd+'T12:00'));
 ['todayText','selectedDateLabel','routineDateLabel'].forEach(id=>{const el=document.getElementById(id);if(el)el.textContent=(id==='todayText'?'Data selecionada: ':'')+label});['datePicker','routinePicker'].forEach(id=>{const el=document.getElementById(id);if(el)el.value=sd});
 const set=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v};set('goalValue',money(goal));set('goalPct',pct.toFixed(1).replace('.',',')+'% concluído');set('remaining',remaining? 'Faltam '+money(remaining):'Meta atingida');set('goalBasis','Ciclo: '+formatDate(data.periodStart)+' → '+formatDate(data.periodEnd));const bar=document.getElementById('goalBar');if(bar)bar.style.width=pct+'%';
 set('dailyGoal',plannedGoalFor(sd)?money(plannedGoalFor(sd)):'—');set('todayIncome',money(incomeForDay(sd)));set('todayExpense',money(sum(data.expenses.filter(x=>x.date===sd),x=>x.amount)));set('incomeAccumulated',money(income));set('netValue',money(net));
 set('statusText',dayTarget?(closed?(dayDiff>=0?'🟢 Dia concluído: excedente de '+money(dayDiff)+'.':'🔴 Dia concluído: faltaram '+money(-dayDiff)+'.'):(dayGain>=dayTarget?'🟢 Você já atingiu a meta do dia. O dia ainda está aberto.':'🟡 Faltam '+money(dayTarget-dayGain)+' para a meta do dia.')):'🔵 Sem meta financeira de trabalho neste dia.');set('averageText','Para terminar o ciclo no objetivo: '+money(needed)+' por dia de trabalho ainda aberto.');
 let audit='Planejamento restante: <b>'+money(futurePlan)+'</b> • ';if(Math.abs(gap)<0.5)audit+='🟢 Alinhado com o que ainda falta ganhar.';else if(gap>0)audit+='🟠 Faltam <b>'+money(gap)+'</b> no planejamento restante. Você escolhe onde redistribuir.';else audit+='🟢 Há <b>'+money(excess)+'</b> acima do necessário no planejamento dos dias abertos. Isso é margem de planejamento, não uma dívida e não altera a meta do ciclo.';if(closedDeficit>0.5)audit+=' • 🔴 Déficit acumulado dos dias concluídos: <b>'+money(closedDeficit)+'</b>.';if(closedSurplus>0.5)audit+=' • 🟢 Excedente dos dias concluídos: <b>'+money(closedSurplus)+'</b>.';const pa=document.getElementById('planAudit');if(pa)pa.innerHTML=audit;const pc=document.getElementById('planningControls');if(pc){pc.innerHTML=`<div class="summaryLine"><b>Meta necessária agora:</b> ${money(needed)} por dia de trabalho ainda aberto • <b>${days}</b> dia(s) aberto(s).</div><div class="summaryLine"><b>Falta ganhar:</b> ${money(remaining)}${closedDeficit>0.5?` • <b>Déficit acumulado:</b> ${money(closedDeficit)}`:''}${closedSurplus>0.5?` • <b>Excedente acumulado:</b> ${money(closedSurplus)}`:''}</div><div class="quick"><button onclick="editWeeklyTargets()">✏️ Editar metas por dia</button><button onclick="editWeeklyActivities()">⚙️ Editar rotina semanal</button>${gap>0.5?`<button onclick="openRedistribute()">🔄 Redistribuir + ${money(gap)}</button>`:''}</div>`}
 const q=data.quality[sd]||{};set('qualitySummary','Em '+formatDate(sd)+': treino – '+(q.treino||'não registrado')+' | alimentação – '+(q.alimentacao||'não registrada'));
 const rows=dayPlan(sd);const html=rows.map(a=>{const p=activityProgress(a,sd);return `<div class="routineRow ${p.pct>=100?'done':''}"><div><strong>${esc(a.icon)} ${esc(a.name)}</strong><small>${a.metric==='money'?'Meta financeira: '+money(p.target):a.metric==='hours'?'Meta de tempo: '+p.target+'h': 'Meta de conclusão'} • ${esc(p.label)}</small><div class="miniProgress"><span style="width:${p.pct}%"></span></div></div><div class="rowActions"><button onclick="editActivity('${sd}','${esc(a.id)}')">Editar</button><button class="danger" onclick="deleteActivity('${sd}','${esc(a.id)}')">Excluir</button>${a.metric==='check'?`<input type="checkbox" ${a.done?'checked':''} onchange="toggleActivity('${sd}','${esc(a.id)}')">`:''}</div></div>`}).join('');
